function makeSpray() {
  const group = new THREE.Group(), droplets = [];
  const geo = new THREE.SphereGeometry(1, 8, 6);
  for (let i = 0; i < 66; i++) {
    const u = .08 + random() * .82;
    const p = wavePoint(u, 7.45 / 15);
    const r = .022 + random() * .035;
    const drop = mesh(geo, i % 4 ? mats.foam : mats.mint, group, [p.x, p.y, p.z], [r, r * 1.5, r]);
    drop.castShadow = false; drop.receiveShadow = false;
    droplets.push({ mesh: drop, origin: p, phase: random(), speed: .3 + random() * .25, height: .4 + random() * .75, distance: .4 + random() * .7, radius: r });
  }
  for (let i = 0; i < 22; i++) {
    const r = .025 + random() * .04;
    const origin = v3(-1.5 + random() * .9, .22, 1.6 + random() * .5);
    const drop = mesh(geo, mats.foam, group, [0, 0, 0], [r, r, r]);
    drop.castShadow = false;
    droplets.push({ mesh: drop, origin, phase: random(), speed: .65 + random() * .3, height: .25 + random() * .65, distance: .8, radius: r });
  }
  return { group, animate(t) {
    droplets.forEach(d => {
      const life = (t * d.speed + d.phase) % 1;
      d.mesh.position.set(d.origin.x - life * .45, d.origin.y + Math.sin(life * Math.PI) * d.height - life * .3, d.origin.z + life * d.distance);
      const s = d.radius * Math.pow(Math.sin(life * Math.PI), .6);
      d.mesh.scale.set(s, s * (1.3 - life * .5), s);
    });
  } };
}

