  background: #eeeddf;
  font-synthesis: none;
  -webkit-font-smoothing: antialiased;
  font-weight: 400;
}

* { box-sizing: border-box; }
html, body { margin: 0; width: 100%; min-height: 100%; overflow-x: hidden; }
body { min-width: 320px; }

.page {
  position: relative;
  width: 100%;
  height: 100svh;
  min-height: 740px;
  overflow: hidden;
  background: radial-gradient(ellipse at 69% 40%, #f7f1de 0%, #efeedf 53%, #e9ecdf 100%);
}

/* Quiet editorial framing around an entirely non-interactive scene. */
.masthead {
  position: absolute;
  z-index: 5;
  top: 0;
  left: 4.5%;
  right: 4.5%;
  height: 109px;
  border-bottom: 1px solid #244c462e;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.brand { display: flex; align-items: center; gap: 11px; }
.brand-mark {
  width: 40px;
  height: 31px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.wordmark {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 42px;
  font-style: italic;
  font-weight: 700;
  letter-spacing: -3px;
  line-height: 1;
  margin-top: -6px;
}
.brand-description {
  font-size: 9px;
  font-weight: 600;
  line-height: 1.6;
  letter-spacing: 2px;
  border-left: 1px solid #244c463b;
  padding-left: 19px;
  margin-left: 15px;
}
.edition { display: flex; align-items: center; gap: 45px; font-size: 9px; letter-spacing: 1.6px; }
.edition-number { font-size: 10px; letter-spacing: 1.4px; }
.edition-number i { font-style: normal; font-size: 20px; margin-left: 15px; font-weight: 400; }
main { position: absolute; inset: 0; }

.intro {
  position: absolute;
  z-index: 3;
  left: 7.2%;
  top: 21.5%;
  pointer-events: none;
}
.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  letter-spacing: 2.2px;
  font-weight: 600;
  margin: 0 0 32px;
}
.eyebrow > span { width: 20px; height: 1px; background: #bb7157; }
h1 {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: clamp(105px, 10.8vw, 164px);
  line-height: .88;
  letter-spacing: -9px;
  font-weight: 400;
  font-style: italic;
  margin: 0 0 31px -10px;
}
.period { color: #c87553; }
.intro-copy { font-size: 14px; line-height: 1.85; letter-spacing: .15px; margin: 0; color: #52665b; }
.intro-note {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-top: 30px;
  font-family: Georgia, 'Times New Roman', serif;
  font-style: italic;
  font-size: 13px;
  color: #7a8674;
}
.note-line { display: block; width: 24px; height: 1px; background: #98a28d; }

#scene {
  position: absolute;
  z-index: 2;
  left: 18%;
  top: 5%;
  width: 84%;
  height: 91%;
  pointer-events: none;
}
#scene canvas { width: 100%; height: 100%; display: block; }
.sun-disc {
  position: absolute;
  left: 65%;
  top: 20%;
  width: 24vw;
  height: 24vw;
  max-width: 380px;
  max-height: 380px;
  border-radius: 50%;
  background: linear-gradient(145deg, #f1ce94, #e9b581);
  opacity: .71;
}
.sun-orbit {
  position: absolute;
  left: 63.6%;
  top: calc(20% - 20px);
  width: calc(24vw + 40px);
  height: calc(24vw + 40px);
  max-width: 420px;
  max-height: 420px;
  border: 1px solid #c7aa7830;
  border-radius: 50%;
}
.distant-birds {
  position: absolute;
  z-index: 1;
  left: 42%;
  top: 19%;
  width: 220px;
  height: 85px;
  fill: none;
  stroke: #78978a;
  stroke-width: 1.5;
  stroke-linecap: round;
  opacity: .58;
}
.sun-stamp {
  position: absolute;
  z-index: 3;
  right: 7%;
  top: 16.7%;
  width: 111px;
  height: 111px;
  transform: rotate(12deg);
  color: #31574b;
}
.sun-stamp svg { width: 100%; height: 100%; overflow: visible; }
.sun-stamp text { font-family: Arial, Helvetica, sans-serif; font-size: 9px; letter-spacing: 2.4px; fill: currentColor; }
.stamp-sun {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.25;
  stroke-linecap: round;
  transform-origin: 60px 60px;
  animation: sun-turn 90s linear infinite;
}
.margin-note {
  position: absolute;
  z-index: 3;
  right: 2.2%;
  top: 44%;
  writing-mode: vertical-rl;
  display: flex;
  align-items: center;
  gap: 16px;
  font-size: 8px;
  letter-spacing: 1.8px;
  color: #688073;
}
.margin-rule { width: 1px; height: 45px; background: #244c4640; }
.scene-caption {
  position: absolute;
  z-index: 3;
  left: 57%;
  bottom: 14%;
  display: flex;
  align-items: center;
  gap: 13px;
}
.caption-index {
  width: 30px;
  height: 30px;
  border: 1px solid #244c4652;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-family: Georgia, 'Times New Roman', serif;
  font-style: italic;
}
.scene-caption > div { display: flex; flex-direction: column; gap: 5px; }
.caption-title { font-size: 8px; letter-spacing: 2px; font-weight: 600; }
.caption-subtitle { font-family: Georgia, 'Times New Roman', serif; font-size: 12px; font-style: italic; color: #6d8070; }

.footer {
  position: absolute;
  z-index: 4;
  bottom: 0;
  left: 4.5%;
  right: 4.5%;
  height: 84px;
  border-top: 1px solid #244c462e;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
}
.live-status, .conditions { display: flex; align-items: center; gap: 10px; font-size: 8px; letter-spacing: 1.55px; font-weight: 600; }
.live-dot {
  width: 6px;
  height: 6px;
  display: block;
  background: #c87c59;
  border-radius: 50%;
  box-shadow: 0 0 0 4px #c87c5912;
  animation: breath 4s ease-in-out infinite;
}
.footer p { font-family: Georgia, 'Times New Roman', serif; font-size: 15px; font-style: italic; letter-spacing: .1px; margin: 0; color: #687a69; }
.conditions svg { width: 29px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.2; }
.paper-grain { position: absolute; z-index: 10; inset: 0; pointer-events: none; mix-blend-mode: multiply; opacity: .13; }
.fallback { display: flex; align-items: center; justify-content: center; font-family: Georgia, serif; font-style: italic; font-size: 22px; color: #244c46; }

@keyframes breath { 50% { opacity: .5; box-shadow: 0 0 0 6px #c87c5900; } }
@keyframes sun-turn { to { transform: rotate(360deg); } }

@media (min-width: 1700px) {
  .intro { top: 23%; }
  h1 { font-size: 180px; }
  .intro-copy { font-size: 17px; }
  .eyebrow { font-size: 11px; }
  .intro-note { font-size: 15px; }
}

@media (max-width: 1100px) {
  .masthead { height: 94px; }
  .edition { gap: 25px; }
  .edition > span:first-child { font-size: 8px; letter-spacing: 1px; }
  .intro { left: 6%; top: 23%; }
  h1 { font-size: clamp(90px, 10.5vw, 117px); letter-spacing: -7px; }
  .eyebrow { font-size: 8px; letter-spacing: 1.7px; margin-bottom: 28px; }
  .intro-copy { font-size: 12px; }
  .intro-note { font-size: 12px; }
  #scene { left: 24%; width: 80%; top: 8%; height: 88%; }
  .sun-stamp { right: 6%; width: 92px; height: 92px; }
  .scene-caption { bottom: 14.5%; left: 60%; }
  .footer p { font-size: 13px; }
  .footer { height: 74px; }
  .live-status, .conditions { font-size: 7px; letter-spacing: 1.1px; }
}

@media (max-width: 760px) {
  .page { min-height: 840px; height: 100svh; }
  .masthead { left: 6%; right: 6%; height: 85px; }
  .wordmark { font-size: 35px; }
  .brand-mark { width: 31px; }
  .brand-description { font-size: 7px; letter-spacing: 1.5px; margin-left: 10px; padding-left: 13px; }
  .edition > span:first-child { display: none; }
  .edition-number { font-size: 8px; }
  .edition-number i { font-size: 17px; margin-left: 7px; }
  .intro { top: 125px; left: 9%; }
  .eyebrow { font-size: 8px; margin-bottom: 23px; }
  h1 { font-size: 101px; letter-spacing: -6px; line-height: .84; margin-bottom: 23px; }
  .intro-copy { font-size: 12px; line-height: 1.7; }
  .intro-note { display: none; }
  #scene { left: -16%; top: 27%; width: 132%; height: 64%; }
  .sun-disc { left: 51%; top: 30%; width: 42vw; height: 42vw; max-width: none; max-height: none; }
  .sun-orbit { left: calc(51% - 12px); top: calc(30% - 12px); width: calc(42vw + 24px); height: calc(42vw + 24px); }
  .sun-stamp { top: 131px; right: 9%; width: 83px; height: 83px; }
  .distant-birds { left: 57%; top: 27%; width: 133px; }
  .margin-note { display: none; }
  .scene-caption { left: 50%; transform: translateX(-50%); bottom: 12%; white-space: nowrap; }
  .footer { left: 6%; right: 6%; height: 72px; align-items: center; flex-wrap: wrap; gap: 0; }
  .footer p { font-size: 12px; }
  .conditions { display: none; }
  .live-status { font-size: 7px; gap: 8px; letter-spacing: .8px; }
  .paper-grain { opacity: .1; }
}

@media (max-width: 390px) {
  .footer p { font-size: 10px; }
  .intro { left: 8%; }
  h1 { font-size: 90px; }
  .sun-stamp { right: 7%; width: 75px; }
}

@media (prefers-reduced-motion: reduce) {
  .stamp-sun, .live-dot { animation: none; }
}

